"""Namespace, element and unit helpers for WordprocessingML.

Only the standard library is used: ``xml.etree.ElementTree`` covers everything
we need and keeps the package free of compiled dependencies.
"""
from __future__ import annotations

from xml.etree import ElementTree as ET

NS = {
    'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main',
    'w14': 'http://schemas.microsoft.com/office/word/2010/wordml',
    'w15': 'http://schemas.microsoft.com/office/word/2012/wordml',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
    'a': 'http://schemas.openxmlformats.org/drawingml/2006/main',
    'pic': 'http://schemas.openxmlformats.org/drawingml/2006/picture',
    'wp': 'http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing',
    'wp14': 'http://schemas.microsoft.com/office/word/2010/wordprocessingDrawing',
    'wps': 'http://schemas.microsoft.com/office/word/2010/wordprocessingShape',
    'mc': 'http://schemas.openxmlformats.org/markup-compatibility/2006',
    'v': 'urn:schemas-microsoft-com:vml',
    'o': 'urn:schemas-microsoft-com:office:office',
    'm': 'http://schemas.openxmlformats.org/officeDocument/2006/math',
    'ct': 'http://schemas.openxmlformats.org/package/2006/content-types',
    'pr': 'http://schemas.openxmlformats.org/package/2006/relationships',
    'xml': 'http://www.w3.org/XML/1998/namespace',
}

for _prefix, _uri in NS.items():
    if _prefix != 'xml':
        ET.register_namespace(_prefix, _uri)

W = NS['w']


def qn(name: str) -> str:
    """``'w:val'`` -> ``'{http://...}val'``."""
    prefix, _, local = name.partition(':')
    if not local:
        return prefix
    return '{%s}%s' % (NS[prefix], local)


_path_cache: dict[str, str] = {}


def xp(path: str) -> str:
    """Translate a prefixed ElementPath (``'w:pPr/w:ind'``) to Clark notation."""
    out = _path_cache.get(path)
    if out is None:
        parts = []
        for step in path.split('/'):
            if step in ('.', '..', '*', ''):
                parts.append(step)
            elif ':' in step:
                parts.append(qn(step))
            else:
                parts.append(step)
        out = '/'.join(parts)
        _path_cache[path] = out
    return out


def find(el, path):
    if el is None:
        return None
    return el.find(xp(path))


def findall(el, path):
    if el is None:
        return []
    return el.findall(xp(path))


def get(el, name, default=None):
    if el is None:
        return default
    v = el.get(qn(name))
    return default if v is None else v


def val(el, default=None):
    """The ``w:val`` attribute of *el* (``None`` when *el* is missing)."""
    if el is None:
        return default
    return el.get(qn('w:val'), default)


def child_val(parent, path, default=None):
    return val(find(parent, path), default)


def on_off(el, default=True):
    """Interpret an on/off element (``<w:b/>``, ``<w:b w:val="0"/>`` ...).

    Returns ``None`` when the element is absent so callers can distinguish
    "not specified" (inherit) from "explicitly off".
    """
    if el is None:
        return None
    v = el.get(qn('w:val'))
    if v is None:
        return default
    return v not in ('0', 'false', 'off')


def int_of(text, default=None):
    if text is None:
        return default
    try:
        return int(round(float(text)))
    except (TypeError, ValueError):
        return default


def float_of(text, default=None):
    if text is None:
        return default
    try:
        return float(text)
    except (TypeError, ValueError):
        return default


def local(tag: str) -> str:
    """Local name of a Clark-notation tag."""
    return tag.rpartition('}')[2]


# -- units ------------------------------------------------------------------
# Word stores lengths in twentieths of a point (twips/dxa), half-points (font
# sizes), eighths of a point (border widths) and EMUs (drawing sizes).

EMU_PER_PT = 12700.0
TWIP_PER_PT = 20.0


def twips(v, default=None):
    """dxa/twips -> points."""
    n = float_of(v)
    return default if n is None else n / TWIP_PER_PT


def emu(v, default=None):
    n = float_of(v)
    return default if n is None else n / EMU_PER_PT


def half_points(v, default=None):
    n = float_of(v)
    return default if n is None else n / 2.0


def eighth_points(v, default=None):
    n = float_of(v)
    return default if n is None else n / 8.0


def pct50(v, default=None):
    """``w:shd`` ``w:tblW`` style pct values (fiftieths of a percent)."""
    n = float_of(v)
    if n is None:
        return default
    return n / 5000.0
